mapper.insert:

	select BOOK_SEQ.nextval from dual  

  insert into BOOK_TBL_06(
		BOOK_NO           
		,BOOK_NAME              
		,BOOK_COVERIMG           
		,BOOK_DATE                   
		,BOOK_PRICE              
		,BOOK_PUBLISHER          
		,BOOK_INFO  )
  values (
   #{bookNo}
  ,#{bookName}
  ,#{bookCoverimg}
  ,#{bookDate}
  ,#{bookPrice}
  ,#{bookPublisher}
  ,#{bookInfo}
)
